import sys

def max_alternating_sum(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    # Initialize the dp array
    dp = [0] * n
    dp[0] = arr[0]
    dp[1] = max(arr[0], arr[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + arr[i])

    return max(dp)

