def is_fascinating(n):
    n = str(n)
    n2 = str(2 * n)
    n3 = str(3 * n)
    concatenated = n + n2 + n3
    if len(concatenated) != 9:
        return False
    if '0' in concatenated:
        return False
    if sorted(concatenated) != list('123456789'):
        return False
    return True

