def isPossible(nums):
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if gcd(nums[i], nums[j]) > 1:
                graph[i].append(j)
                graph[j].append(i)
    return all(len(graph[i]) == len(set(graph[i])) for i in range(len(nums)))

