def minTime(nums1, nums2, x):
    n = len(nums1)
    dp = [[float('inf')] * (x + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(x + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums1[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums1[i - 1]] + 1)
            if j >= nums2[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums2[i - 1]] + 1)
            if j >= nums1[i - 1] + nums2[i - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 1][j - nums1[i - 1] - nums2[i - 1]] + 1)

    return dp[n][x] if dp[n][x] != float('inf') else -1

def maxSumAlmostUniqueSubarray(nums, m, k):
    from collections import Counter

    max_sum = 0
    current_sum = 0
    element_count = Counter()

    for i in range(len(nums)):
        element_count[nums[i]] += 1
        current_sum += nums[i]

        if i >= k - 1:
            element_count[nums[i - k + 1]] -= 1
            if element_count[nums[i - k + 1]] == 0:
                del element_count[nums[i - k + 1]]
            current_sum -= nums[i - k + 1]

            if len(element_count) >= m:
                max_sum = max(max_sum, current_sum)

    return max_sum

