def minOperations(num: str) -> int:
    n = len(num)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1 if num[i] == '0' else 0
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if num[i] == '0':
