def max_element_sum(nums):
    n = len(nums)
    dp = [0] * (n + 1)
    max_sum = 0

    for i in range(1, n + 1):
        for j in range(i):
            product = nums[j - 1] * nums[i - 1]
            if product == math.isqrt(product) ** 2:
                dp[i] = max(dp[i], dp[j] + nums[i - 1])
                max_sum = max(max_sum, dp[i])

    return max_sum

def subMultisets(nums, l, r):
