def subarrays(nums, k):
    count = 0
    max_num = max(nums)
    left = 0

    for right in range(len(nums)):
        if nums[right] == max_num:
            count += right - left + 1

        while nums[right] == max_num and right - left + 1 >= k:
            count -= right - left
            left += 1

