def countCompleteSubstrings(word, k):
    def is_complete(s):
        count = {}
        for c in s:
            if c in count:
                count[c] += 1
            else:
                count[c] = 1
        for v in count.values():
            if v != k:
                return False
        return True

    def is_valid(s):
        for i in range(len(s) - 1):
            if abs(ord(s[i]) - ord(s[i + 1])) > 2:
                return False
        return True

    count = 0
    for i in range(len(word)):
        for j in range(i + 1, len(word) + 1):
            if is_valid(word[i:j]) and is_complete(word[i:j]):
                count += 1
    return count

