def minOr(nums, k):
    n = len(nums)
    dp = [[0]*31 for _ in range(n+1)]
    for i in range(n):
        dp[i+1][0] = nums[i]
        for j in range(1, 31):
            dp[i+1][j] = min(dp[i+1][j], dp[i][j])
    for i in range(n-1, -1, -1):
        for j in range(1, 31):
            dp[i][j] = min(dp[i][j], dp[i+1][j])
            dp[i][j] = min(dp[i][j], dp[i+1][j-1] & nums[i])
    return min(dp[0][j] for j in range(31))

def largestPerimeter(nums):
