    total = sum(nums)
    if total < 3:
        return -1
    for i in range(len(nums)-2):
        if nums[i] + nums[i+1] > nums[i+2]:
            return total - nums[i+2]
    return total - nums[-1]

def can_sort(nums):
    def count_set_bits(n):
        return bin(n).count('1')

    def swap_if_possible(i, j):
        if count_set_bits(nums[i]) == count_set_bits(nums[j]):
            nums[i], nums[j] = nums[j], nums[i]

    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if count_set_bits(nums[i]) == count_set_bits(nums[j]):
                swap_if_possible(i, j)
    return nums == sorted(nums)

def earliestSecondToMarkIndices(nums, changeIndices):
    n = len(nums)
    m = len(changeIndices)

    # Initialize the dp array
    dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    # Fill the dp array
    for i in range(1, n + 1):
        for s in range(1, m + 1):
            if nums[i - 1] > 0:
                dp[i][s] = min(dp[i][s], dp[i - 1][s - 1] + 1)
            if s < m and changeIndices[s - 1] <= i:
                dp[i][s] = min(dp[i][s], dp[changeIndices[s - 1] - 1][s - 1] + 1)

    # Check if all indices can be marked
    for i in range(1, n + 1):
        if dp[i][m] == float('inf'):
            return -1

    return dp[n][m]

def returnToBoundary(nums):
    left_boundary = 0
    right_boundary = 0
    return_count = 0

    for num in nums:
        if num < 0:
            left_boundary += -num
        else:
            right_boundary += num

        if left_boundary == 0 or right_boundary == 0:
            return_count += 1

    return return_count

