        if S[i] == 'T':
            takahashi_wins += 1
        else:
            aoki_wins += 1
    if takahashi_wins > aoki_wins:
        return 'T'
    elif aoki_wins > takahashi_wins:
        return 'A'
    else:
        for i in range(N):
