import sys
from collections import deque

def bfs(grid, start, goal, T):
    H, W = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(start, 0)])
    visited = set()
    visited.add(start)
    candies = set()

    while queue:
        (x, y), moves = queue.popleft()
        if (x, y) == goal:
            return len(candies)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), moves + 1))
                if grid[nx][ny] == 'o':
                    candies.add((nx, ny))

    return -1

def main():
    H, W, T = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]
    start = None
    goal = None
    candies = set()

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.add((i, j))

    result = bfs(grid, start, goal, T)
    print(result)

if __name__ == "__main__":
    main()

MOD = 998244353

def count_non_ddos_strings(S):
    n = len(S)
    dp = [[[0]*52 for _ in range(52)] for _ in range(52)]
    dp[0][0][0] = 1

    for i in range(n):
        for c in range(52):
            for d in range(52):
                if S[i] == '?':
                    for k in range(52):
                        dp[c][d][k] = (dp[c][d][k] + dp[c][d][k]) % MOD
                else:
                    if S[i].isupper():
                        for k in range(52):
                            dp[ord(S[i]) - ord('A')][d][k] = (dp[ord(S[i]) - ord('A')][d][k] + dp[c][d][k]) % MOD
                    else:
                        for k in range(52):
                            dp[c][ord(S[i]) - ord('a') + 26][d][k] = (dp[c][ord(S[i]) - ord('a') + 26][d][k] + dp[c][d][k]) % MOD

    return sum(dp[0][0][0] for c in range(52) for d in range(52) for k in range(52)) % MOD

