    # Generate all possible positions to paste A and B on C
    def generate_paste_positions(H, W):
        positions = []
        for i in range(H):
            for j in range(W):
                positions.append((i, j))
        return positions

    # Generate all possible positions to cut out a H_X x W_X area from C
    def generate_cut_positions(H, W):
        positions = []
        for i in range(H - H_X + 1):
            for j in range(W - W_X + 1):
                positions.append((i, j))
        return positions

    # Check if the cut-out sheet includes all black squares of sheets A and B
    def check_cut_out(positions, A, B, X):
        for i in range(H_X):
            for j in range(W_X):
                if (i, j) not in positions:
                    continue
                cut_out = [row[j] for row in X]
                if not all(cut_out[i] == '#' for cut_out in [A[i], B[i]]):
                    return False
        return True

    # Check if the cut-out sheet coincides sheet X without rotating or flipping
    def check_coincides(positions, X):
        for i in range(H_X):
            for j in range(W_X):
                if (i, j) not in positions:
                    continue
                if X[i][j] != '#':
                    return False
        return True

    # Generate all possible positions to paste A and B on C
    paste_positions = generate_paste_positions(H_A, W_A)
    cut_positions = generate_cut_positions(H_X, W_X)

    # Check all combinations of pasting A and B and cutting out a H_X x W_X area
    for a_pos in paste_positions:
        for b_pos in paste_positions:
            for cut_pos in cut_positions:
                if check_cut_out([a_pos, b_pos], A, B, X) and check_coincides([a_pos, b_pos], X):
                    return "Yes"
    return "No"

