def find_cycle(N, A):
    visited = [False] * (N + 1)
    path = []

    def dfs(v):
        visited[v] = True
        path.append(v)
        for u in A[v - 1]:
            if not visited[u]:
                dfs(u)
            elif v != u:
                path.append(u)
                return True
        path.pop()
        return False

    for i in range(1, N + 1):
        if not visited[i]:
            dfs(i)
            if len(path) > 2:
                cycle = path[path.index(path[-1]):]
                return len(cycle), cycle

