def is_tak_code(grid, i, j):
    # Check top-left 3x3
    for x in range(i, i+3):
        for y in range(j, j+3):
            if grid[x][y] != '#':
                return False
    # Check bottom-right 3x3
    for x in range(i+6, i+9):
        for y in range(j+6, j+9):
            if grid[x][y] != '#':
                return False
    # Check adjacent cells to top-left 3x3
    for x in range(i-1, i+4):
        for y in range(j-1, j+4):
            if (x < i or x >= i+6 or y < j or y >= j+6) and grid[x][y] != '.':
                return False
    # Check adjacent cells to bottom-right 3x3
    for x in range(i+5, i+10):
        for y in range(j+5, j+10):
            if (x < i+6 or x >= i+9 or y < j+6 or y >= j+9) and grid[x][y] != '.':
