        if S[i] == '(':
            dp[i+1][i+1] = dp[i][i]
        elif S[i] == ')':
            dp[i+1][i+1] = dp[i][i]
        else:
            dp[i+1][i+1] = (dp[i][i] + dp[i+1][i]) % MOD
    for i in range(len(S)-1, -1, -1):
        for j in range(i+1, len(S)+1):
            if S[i] == '(':
                dp[i][j] = (dp[i][j] + dp[i+1][j]) % MOD
            elif S[i] == ')':
                dp[i][j] = (dp[i][j] + dp[i+1][j-1]) % MOD
            else:
                dp[i][j] = (dp[i][j] + dp[i+1][j-1] + dp[i+1][j]) % MOD
    return dp[0][len(S)]

