import heapq

def main():
    N, X, Y = map(int, sys.stdin.readline().split())
    P_T = [tuple(map(int, sys.stdin.readline().split())) for _ in range(N-1)]
    Q = int(sys.stdin.readline())
    queries = [int(sys.stdin.readline()) for _ in range(Q)]

    # Initialize the priority queue with the starting point
    pq = [(0, 0)]  # (time, bus stop)
    visited = [False] * (N + 1)
    visited[0] = True

    while pq:
        time, stop = heapq.heappop(pq)
        if stop == N:
            break
        if time > visited[stop]:
            continue
        for i in range(N):
            if visited[i]:
                continue
            if time % P_T[i-1][0] == 0:
                new_time = time + P_T[i-1][1]
                if new_time < visited[i+1]:
                    visited[i+1] = True
                    heapq.heappush(pq, (new_time, i+1))

    # Process each query
    for q in queries:
        print(q + X + Y)

