def solve(grid):
    def rotate(grid):
        return [list(row) for row in zip(*grid[::-1])]

    def flip(grid):
        return [list(row) for row in zip(*grid[::-1])]

    def translate(grid, dx, dy):
        return [list(row) for row in zip(*grid)]

    def rotate_translate(grid, dx, dy):
        return rotate(translate(grid, dx, dy))

    def flip_translate(grid, dx, dy):
        return flip(translate(grid, dx, dy))

    def is_valid(grid, x, y):
        for i in range(4):
            for j in range(4):
                if grid[x + i][y + j] == '#':
                    return False
        return True

    def place(grid, polyomino, x, y):
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#':
                    grid[x + i][y + j] = '#'

    def remove(grid, polyomino, x, y):
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#':
                    grid[x + i][y + j] = '.'

    def solve_grid(grid, polyominoes):
        for i in range(4):
            for j in range(4):
                if grid[i][j] == '#':
                    for k in range(4):
                        for l in range(4):
                            if grid[i + k][j + l] == '#':
                                return False
        return True

    def solve_polyomino(polyomino, x, y):
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#':
                    place(grid, polyomino, x, y)
                    if solve_grid(grid, polyominoes):
                        return True
                    remove(grid, polyomino, x, y)
        return False

    grid = [list(row) for row in grid]
    polyominoes = [list(row) for row in polyominoes]
    for i in range(4):
        for j in range(4):
            for k in range(4):
                for l in range(4):
                    if grid[i][j] == '#' and grid[i + k][j + l] == '#':
                        polyominoes[i][j] = polyominoes[i][j][:]
                        polyominoes[i][j][k] = '#'
                        polyominoes[i][j][l] = '#'
                        polyominoes[i + k][j + l] = polyominoes[i + k][j + l][:]
                        polyominoes[i + k][j + l][k] = '#'
                        polyominoes[i + k][j + l][l] = '#'
                        if solve_polyomino(polyominoes, i, j):
                            return "Yes"
                        polyominoes[i][j] = polyominoes[i][j][:]
                        polyominoes[i][j][k] = '.'
                        polyominoes[i][j][l] = '.'
                        polyominoes[i + k][j + l] = polyominoes[i + k][j + l][:]
                        polyominoes[i + k][j + l][k] = '.'
                        polyominoes[i + k][j + l][l] = '.'
    return "No"

