    for i, s in enumerate(S):
        if len(s) != len(T):
            continue

        # Check if the string is equal to T
        if s == T:
            result.append(i + 1)

        # Check if the string is obtained by inserting one character
        for c in char_positions:
            if len(s) == len(T) + 1:
                if s[:len(T)] == T:
                    result.append(i + 1)
                    break

        # Check if the string is obtained by deleting one character
        if len(s) == len(T) - 1:
            if s[1:] == T:
                result.append(i + 1)
                break

        # Check if the string is obtained by changing one character
        if len(s) == len(T):
            diff = 0
            for c1, c2 in zip(s, T):
                if c1 != c2:
                    diff += 1
                    if diff > 1:
                        break
            if diff == 1:
