def max_products(events):
    heap = []
    count = 0
    last_print_time = 0

    for time, event_type, duration in events:
        if event_type == 'enter':
            heapq.heappush(heap, (time, duration))
        else:
            while heap and heap[0][1] <= time:
                heapq.heappop(heap)
            if heap:
                last_print_time = heap[0][0]
                count += 1
                heapq.heappop(heap)

    return count

