def solve(N, R, C):
    grid = [['.']*N for _ in range(N)]

    def is_valid(grid, row, col):
        if grid[row][col] != '.':
            return False
        for i in range(N):
            if grid[row][i] != '.' and grid[row][i] != R[i]:
                return False
            if grid[i][col] != '.' and grid[i][col] != C[i]:
                return False
        return True

    def backtrack(row):
        if row == N:
            return True
        for col in range(N):
            if is_valid(grid, row, col):
                grid[row][col] = R[row]
                if backtrack(row + 1):
                    return True
                grid[row][col] = '.'
        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print(''.join(row))
    else:
        print("No")

