def min_operations(H, W, A, B):
    from itertools import permutations

    def is_identical(A, B):
        return all(A[i][j] == B[i][j] for i in range(H) for j in range(W))

    def swap_rows(A, i, j):
        A[i], A[j] = A[j], A[i]

    def swap_cols(A, i, j):
        for k in range(W):
            A[i][k], A[j][k] = A[j][k], A[i][k]

    def count_operations(A, B):
        operations = 0
        for i in range(H):
            for j in range(W):
                if A[i][j] != B[i][j]:
                    if i > 0 and A[i-1][j] != B[i-1][j]:
                        swap_rows(A, i, i-1)
                        operations += 1
                    if j > 0 and A[i][j-1] != B[i][j-1]:
                        swap_cols(A, i, j-1)
                        operations += 1
        return operations

    for perm in permutations(range(H)):
        for perm2 in permutations(range(H)):
            A_perm = [A[i][j] for i in perm for j in range(W)]
            B_perm = [B[i][j] for i in perm2 for j in range(W)]
            if is_identical(A_perm, B_perm):
                return count_operations(A_perm, B_perm)

    return -1

