from collections import deque

def bfs(graph, start):
    visited = [False] * (len(graph) + 1)
    queue = deque([start])
    visited[start] = True
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
    return visited

def min_operations_to_delete_vertex_1(N, edges):
    graph = [[] for _ in range(N + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = bfs(graph, 1)

    if not visited[1]:
        return -1

    queue = deque([(1, 0)])
    visited = [False] * (N + 1)
    visited[1] = True
    operations = 0

    while queue:
        node, operations_count = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((neighbor, operations_count + 1))

    return operations

