def kth_smallest(N, M, K):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def count_divisible(N, M, K):
        return (K + 1) // lcm(N, M)

    def find_kth(N, M, K):
        lcm_NM = lcm(N, M)
        count_N = count_divisible(N, M, K)
        count_M = count_divisible(N, M, K)
        count_NM = count_divisible(N, M, K)
        if count_N > count_M:
            return N * count_N + (K - count_N)
        elif count_M > count_N:
            return M * count_M + (K - count_M)
        else:
            return N * count_N + M * count_M + (K - count_N - count_M)

    return find_kth(N, M, K)

