            for j in range(tile_size):
                grid[x + i][y + j] = False

    grid = [[False] * W for _ in range(H)]
    tiles.sort(key=lambda x: x[0] * x[1])
    for tile_size, tile_count in tiles:
        for _ in range(tile_count):
            for x in range(H - tile_size + 1):
                for y in range(W - tile_size + 1):
                    if can_place(x, y, tile_size):
                        place_tile(x, y, tile_size)
                        if all(grid[i][j] for i in range(H) for j in range(W)):
                            return True
                        remove_tile(x, y, tile_size)
