    def check_win(grid):
        # Check rows, columns, and diagonals for three consecutive cells of the same color
        for i in range(3):
            if grid[i][0] == grid[i][1] == grid[i][2] != 0:
                return True
            if grid[0][i] == grid[1][i] == grid[2][i] != 0:
                return True
        if grid[0][0] == grid[1][1] == grid[2][2] != 0:
            return True
        if grid[0][2] == grid[1][1] == grid[2][0] != 0:
            return True
        return False

    def check_score(grid):
        # Check if there are white cells left
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    return False
        return True

    def minimax(grid, is_maximizing):
        if check_win(grid):
            return 1 if is_maximizing else -1
        if check_score(grid):
            return sum(sum(row) for row in grid)
        if is_maximizing:
            best_score = float('-inf')
            for i in range(3):
                for j in range(3):
                    if grid[i][j] == 0:
                        grid[i][j] = 1 if is_maximizing else -1
                        score = minimax(grid, not is_maximizing)
                        grid[i][j] = 0
                        best_score = max(score, best_score)
            return best_score
        else:
            best_score = float('inf')
            for i in range(3):
                for j in range(3):
                    if grid[i][j] == 0:
                        grid[i][j] = 1 if is_maximizing else -1
                        score = minimax(grid, not is_maximizing)
                        grid[i][j] = 0
                        best_score = min(score, best_score)
            return best_score

    grid = [[0]*3 for _ in range(3)]
    return minimax(grid, True)

