def solve(N, A, X, Y):
    def dp(n):
        if n == 0:
            return 0
        if n == 1:
            return X
        if n == 2:
            return min(X, Y)
        if n == 3:
            return min(X, Y)
        if n == 4:
            return min(X, Y)
        if n == 5:
            return min(X, Y)
        if n == 6:
            return min(X, Y)
        if n % A == 0:
            return dp(n // A)
        else:
            return min(dp(n // 2) + X, dp(n // 3) + X, dp(n // 4) + X, dp(n // 5) + X, dp(n // 6) + X, Y)
    return dp(N)

