def max_degree_of_freedom(H, W, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False]*W for _ in range(H)]
    max_degree = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and not visited[i][j]:
                queue = [(i, j)]
                visited[i][j] = True
                degree = 1

                while queue:
                    x, y = queue.pop(0)
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.' and not visited[nx][ny]:
                            visited[nx][ny] = True
                            queue.append((nx, ny))
                            degree += 1

                max_degree = max(max_degree, degree)

    return max_degree

