from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    M = int(input[idx+1])
    idx += 2
    edges = defaultdict(list)
    for _ in range(M):
        K = int(input[idx])
        C = int(input[idx+1])
        idx += 2
        for i in range(K):
            edges[i+1].append((C, i+1))

    # Union-Find
    parent = list(range(N+1))
    rank = [0]*(N+1)
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] > rank[yr]:
            parent[yr] = xr
        elif rank[xr] < rank[yr]:
            parent[xr] = yr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True

    # Sort edges by weight
    edges = sorted(edges.items(), key=lambda x: x[1][0])

    # Kruskal's algorithm
    mst_weight = 0
    for weight, u in edges:
        if union(u, N):
            mst_weight += weight

    # Check if graph is connected
    if find(1) == find(N):
        print(mst_weight)
    else:
        print(-1)

