def find_remainder(N, L, R):
    low, high = L, R
    while low < high:
        mid = (low + high) // 2
        i = 0
        while (1 << i) * (mid + 1) <= (1 << N):
            i += 1
        j = i - 1
        l = (1 << i) * j
        r = (1 << i) * (j + 1) - 1
        T = query(i, j)
        if T == -1:
            return -1
        elif T < mid:
            high = mid
        else:
            low = mid + 1
    return query(0, 0)

