def minDeletion(word, k):
    from collections import Counter

    freq = Counter(word)
    max_freq = max(freq.values())
    min_freq = min(freq.values())

    if max_freq - min_freq <= k:
        return 0

    deletions = 0
    for freq_val in freq.values():
        if freq_val > max_freq + k:
            deletions += freq_val - (max_freq + k)
            max_freq = max(max_freq, freq_val - k)

    return deletions

def mostFrequentIDs(nums, freq):
    from collections import Counter

    ans = []
    counter = Counter(nums)

    for i in range(len(nums)):
        num = nums[i]
        freq_change = freq[i]

        if freq_change > 0:
            counter[num] += freq_change
        else:
            counter[num] -= freq_change

        ans.append(counter[num])

