def max_prime_distance(nums):
    # Sieve of Eratosthenes to find all primes up to the maximum number in nums
    max_num = max(nums)
    is_prime = [True] * (max_num + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(max_num**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, max_num + 1, i):
                is_prime[j] = False

    # Find the maximum distance between the indices of two prime numbers
    max_distance = 0
    for i in range(len(nums)):
        if is_prime[nums[i]]:
            for j in range(i + 1, len(nums)):
                if is_prime[nums[j]]:
                    max_distance = max(max_distance, abs(i - j))
                    break

    return max_distance

import heapq

def kthSmallestAmount(coins, k):
    heap = []
    heapq.heappush(heap, (0, 0))

    while heap:
        amount, coin_index = heapq.heappop(heap)

        if k == 1:
            return amount

        for i in range(coin_index, len(coins)):
            new_amount = amount + coins[i]
            heapq.heappush(heap, (new_amount, i))

    return -1

